+/// Bind an experiment to the schedule that `reg_widths` and `reg_los` actually
+/// use. The digest covers the validated cache payload (trainer configuration
+/// and all width rows) plus the runtime low-window settings. It intentionally
+/// excludes the cache source so generated and loaded instances must match.
+#[doc(hidden)]
+pub fn runtime_thin_schedule_certificate() -> RuntimeThinScheduleCertificate {
+    assert!(
+        thin_schedule_enabled(),
+        "runtime schedule certificate requires TRAILMIX_THIN_SCHEDULE=1"
+    );
+    let config = thin_schedule_config();
+    let schedule = thin_schedule().expect("thin schedule must be initialized");
+    let heldout = env_usize("TRAILMIX_THIN_HELDOUT", 0);
+    let clz_window = thin_clz_window();
+    let lo_givebacks = [
+        env_usize("TRAILMIX_THIN_LO_A_GIVEBACK", 0),
+        env_usize("TRAILMIX_THIN_LO_B_GIVEBACK", 0),
+        env_usize("TRAILMIX_THIN_LO_CA_GIVEBACK", 0),
+        env_usize("TRAILMIX_THIN_LO_CB_GIVEBACK", 0),
+        env_usize("TRAILMIX_THIN_LO_Q_GIVEBACK", 0),
+    ];
+    let cache_input = std::env::var_os("TRAILMIX_THIN_CACHE_IN").is_some()
+        || std::env::var("LOWQ_Q953_EMBEDDED_SCHEDULE")
+            .ok()
+            .as_deref()
+            == Some("1");
+    let cache_output = std::env::var_os("TRAILMIX_THIN_CACHE_OUT").is_some();
+
+    let mut hasher = Sha3_256::new();
+    hasher.update(b"trailmix-thin-runtime-v2");
+    hasher.update(thin_schedule_cache_bytes(schedule, config));
+    hasher.update((heldout as u64).to_le_bytes());
+    hasher.update((clz_window as u64).to_le_bytes());
+    for giveback in lo_givebacks {
+        hasher.update((giveback as u64).to_le_bytes());
+    }
+    let schedule_sha3_256 = hasher.finalize().into();
+
+    RuntimeThinScheduleCertificate {
+        rows: schedule.widths.len(),
+        train: config.train,
+        margin: config.margin,
+        validate: config.validate,
+        repair_margin: config.repair_margin,
+        seed: config.seed,
+        heldout,
+        clz_window,
+        lo_givebacks,
+        cache_input,
+        cache_output,
+        schedule_sha3_256,

+fn trailmix_q_width_step(wq: usize, wa: usize, wb: usize, wca: usize, wcb: usize) -> usize {
+    let natural = wq.max(1);
+    let target = std::env::var("TRAILMIX_Q_TARGET")
+        .ok()
+        .and_then(|s| s.parse::<usize>().ok());
+    let Some(target) = target else {
+        return trailmix_q_width(wq);
+    };
+    // q budget is computed from the (possibly capped) A/B and ca/cb widths so the
+    // working width 2*ab + 2*cacb + q meets `target` consistently with the resizes.
+    let other = 2 * trailmix_ab_width(wa.max(wb)) + 2 * trailmix_cacb_width(wca.max(wcb));
+    // Q_TARGET=684 retains the audited quotient widths. The two reclaimed
+    // persistent lanes are physical savings and are not added back to q.
+    let budget = target.saturating_sub(other).max(1);
+    // Still honor a global Q_CAP if both are set (take the tighter bound).
+    let capped = natural.min(budget);
+    std::env::var("TRAILMIX_Q_CAP")
+        .ok()
+        .and_then(|s| s.parse::<usize>().ok())
+        .map_or(capped, |cap| capped.min(cap.max(1)))
+        .max(1)

+    if lowq_q953_srot_counter67_enabled() {
+        assert!(
+            (3..=5).contains(&owned.len()),
+            "Q953 owned shift-lane count drift"
+        );
+        assert_eq!(counter.len(), 8, "Q953 counter width drift");
+        let mut split: Vec<&QReg> = owned.iter().collect();
+        split.extend(counter[owned.len() + 3..].iter());
+        assert_eq!(split.len(), 5, "Q953 logical shift-lane width drift");
+        body(&split)

+fn hash_tail_nonce(mut hasher: sha3::Shake256, nonce: u64, q0: u32, q1: u32) -> sha3::Shake256 {
+    for i in 0..TRAILMIX_TAIL_NONCE_BITS {
+        let q = if (nonce >> i) & 1 == 1 { q1 } else { q0 };
+        let op = tail_nonce_x_op(q);
+        crate::point_add::B::update_fiat_hash_op(&mut hasher, &op);
+        crate::point_add::B::update_fiat_hash_op(&mut hasher, &op);
+    }

+pub fn mod_mul_canonical_mbu(circ: &mut Circuit, result: &[QReg], a: &[QReg], b: &[QReg]) {
+    assert_eq!(result.len(), 257);
+    assert_eq!(a.len(), 257);
+    assert_eq!(b.len(), 257);
+    let prev = circ.push_section("mul_canonical");
+
+    // b[256] is the required clean top lane, so the scalar bits are
+    // b[255]..b[0].  As with the raw route, omit the first doubling because
+    // result starts at zero.
+    crate::point_add::trailmix_port::mod_arith::controlled_mod_add_canonical_mbu(
+        circ, &b[255], result, a,
+    );
+    for i in (0..255).rev() {
+        crate::point_add::trailmix_port::mod_arith::mod_double_canonical_mbu(circ, result);
+        crate::point_add::trailmix_port::mod_arith::controlled_mod_add_canonical_mbu(
+            circ, &b[i], result, a,
+        );
+    }

+pub(crate) fn emit_inverse<F: FnOnce(&mut B)>(b: &mut B, f: F) {
+    if b.count_only {
+        let snap = b.count_snapshot();
+        if b.fiat_hash.is_some() {
+            let hash_before = b.fiat_hash.clone();
+            b.count_only_capture_stack.push(Vec::new());
+            f(b);
+            let forward = b
+                .count_only_capture_stack
+                .pop()
+                .expect("count-only inverse capture stack");
+            b.restore_count_snapshot(snap);
+            b.fiat_hash = hash_before;
+            emit_inverse_ops_allowing_clean_resets(
+                b,
+                &forward,
+                "count-only hashed emit_inverse",
+            );
+            return;

+    // pairs at the very end of the op stream. For each of NONCE_BITS bits, emit
+    // one X;X pair (an exact identity, since X^2 = I) targeting tx[0] when the
+    // bit is 0 or tx[1] when the bit is 1. The block length is constant
+    // (2*NONCE_BITS ops), so the op count and circuit action are unchanged and
+    // the Toffoli count and peak qubit width are unaffected; only the per-op
+    // target of this tail varies with the nonce, which reseeds the SHAKE256-
+    // derived 9024 Fiat-Shamir test inputs. This selects which random test set
+    // the circuit is validated against without tuning the circuit to it. Gated
+    // on DIALOG_TAIL_NONCE so the stream is byte-identical when it is absent.
+    if let Some(nonce) = std::env::var("DIALOG_TAIL_NONCE")
+        .ok()
+        .and_then(|s| s.parse::<u64>().ok())
+    {
+        const NONCE_BITS: u32 = 48;
+        b.set_phase("dialog_tail_nonce");
+        for i in 0..NONCE_BITS {
+            let q = if (nonce >> i) & 1 == 1 { tx[1] } else { tx[0] };
+            b.x(q);
+            b.x(q);
+        }
+    }

+    // Phase 3: lambda = dy/dx (dx, dy preserved).
+    circ.set_section("ec3.inv_fwd");
+    let dx_inner = std::mem::take(tx);
+    let dy_vec = std::mem::take(ty);
+    let register_shared = register_shared_eea_enabled();
+    let (dx_inner, dy_vec, lambda) = if register_shared {
+        register_shared_divide_forward(circ, dx_inner, dy_vec)
+    } else {
+        shrunken_pz_divide_forward(circ, dx_inner, dy_vec)
+    };

