+/// Explicit proof/profile override for the coefficient nonnegative-predicate cut.
+pub const Q873_COEFFICIENT_NONNEGATIVE_X_CANCEL_ENV: &str =
+    "LOWQ_Q873_COEFFICIENT_NONNEGATIVE_X_CANCEL";
+
+/// The production route sets this feature's default before generation. Keep
+/// the lower-level fallback off so focused proof binaries can test both modes.
+pub const Q873_COEFFICIENT_NONNEGATIVE_X_CANCEL_SOURCE_BAKE: bool = false;
+
+#[derive(Clone, Copy, Debug, Eq, PartialEq)]
+enum CoefficientNonnegativeBracket {
+    Legacy,
+    CancelMiddleX,
+}
+
+#[must_use]
+fn production_coefficient_nonnegative_bracket() -> CoefficientNonnegativeBracket {
+    static BRACKET: std::sync::OnceLock<CoefficientNonnegativeBracket> = std::sync::OnceLock::new();
+
+    *BRACKET.get_or_init(|| {
+        let enabled = match std::env::var(Q873_COEFFICIENT_NONNEGATIVE_X_CANCEL_ENV) {
+            Ok(value) => match value.as_str() {
+                "0" => false,
+                "1" => true,
+                _ => panic!(
+                    "{Q873_COEFFICIENT_NONNEGATIVE_X_CANCEL_ENV} must be exactly 0 or 1, got {value:?}"
+                ),
+            },
+            Err(std::env::VarError::NotPresent) => {
+                Q873_COEFFICIENT_NONNEGATIVE_X_CANCEL_SOURCE_BAKE
+            }
+            Err(error) => panic!(
+                "invalid {Q873_COEFFICIENT_NONNEGATIVE_X_CANCEL_ENV}: {error}"
+            ),
+        };
+        if enabled {
+            CoefficientNonnegativeBracket::CancelMiddleX
+        } else {
+            CoefficientNonnegativeBracket::Legacy
+        }
+    })
+}
+
+#[must_use]
+pub fn q873_coefficient_nonnegative_x_cancel_enabled() -> bool {
+    production_coefficient_nonnegative_bracket() == CoefficientNonnegativeBracket::CancelMiddleX
